"use strict";(globalThis.webpackChunkstory=globalThis.webpackChunkstory||[]).push([[60101],{3696(e){e.exports=JSON.parse('{"tag":{"label":"ai-900","permalink":"/docs/tags/ai-900","allTagsPath":"/docs/tags","count":21,"items":[{"id":"ai-900/workshop-4-azure-ml/azure-ml-overview","title":"1. Azure Machine Learning Overview","description":"Understand what Azure Machine Learning is, its key components, and why it is the platform of choice for building custom ML solutions on Azure.","permalink":"/docs/ai-900/workshop-4-azure-ml/azure-ml-overview"},{"id":"ai-900/workshop-6-computer-vision/cv-concepts","title":"1. Computer Vision Concepts","description":"Understand how machines interpret visual information \u2014 the core Computer Vision tasks, how CNNs work conceptually, and the critical distinctions that AI-900 tests most often.","permalink":"/docs/ai-900/workshop-6-computer-vision/cv-concepts"},{"id":"ai-900/workshop-8-responsible-ai/rai-principles","title":"1. Microsoft\'s Responsible AI Principles","description":"Microsoft\'s 6 Responsible AI principles \u2014 definition, real-world examples, failure cases, and the unavoidable trade-offs between principles when they conflict.","permalink":"/docs/ai-900/workshop-8-responsible-ai/rai-principles"},{"id":"ai-900/workshop-5-nlp/nlp-concepts","title":"1. NLP Concepts and Pipeline","description":"Understand what NLP is, the core tasks it enables, and how an NLP pipeline transforms raw text into structured insights \u2014 the conceptual foundation for AI-900 language workloads.","permalink":"/docs/ai-900/workshop-5-nlp/nlp-concepts"},{"id":"ai-900/workshop-1-intro-ai/what-is-ai","title":"1. What is Artificial Intelligence?","description":"Understand what Artificial Intelligence is, why it matters, and how it differs from traditional rule-based programming \u2014 the starting point for the AI-900 exam.","permalink":"/docs/ai-900/workshop-1-intro-ai/what-is-ai"},{"id":"ai-900/workshop-2-azure-ai/azure-ai-overview","title":"1. What is Azure AI?","description":"Understand what Azure AI is, why organizations use managed AI services instead of building from scratch, and how Azure AI Foundry serves as the unified development platform.","permalink":"/docs/ai-900/workshop-2-azure-ai/azure-ai-overview"},{"id":"ai-900/workshop-7-generative-ai/what-is-genai","title":"1. What is Generative AI?","description":"Understand what Generative AI is, how Large Language Models work, and the fundamental shift from analytical AI to content-creating AI \u2014 the most rapidly evolving area in AI-900.","permalink":"/docs/ai-900/workshop-7-generative-ai/what-is-genai"},{"id":"ai-900/workshop-3-ml-fundamentals/ml-types","title":"1. What is Machine Learning?","description":"Understand what Machine Learning is, why it matters, and the key distinction between supervised and unsupervised learning \u2014 the conceptual foundation for AI-900 exam domain 2.","permalink":"/docs/ai-900/workshop-3-ml-fundamentals/ml-types"},{"id":"ai-900/workshop-1-intro-ai/ai-ml-dl","title":"2. AI, Machine Learning, and Deep Learning","description":"Understand the containment hierarchy AI \u2283 ML \u2283 DL with definitions, trade-offs, and a practical decision framework.","permalink":"/docs/ai-900/workshop-1-intro-ai/ai-ml-dl"},{"id":"ai-900/workshop-2-azure-ai/azure-ai-services","title":"2. Azure AI Services","description":"A detailed reference for all seven Azure AI prebuilt services covered in AI-900 \u2014 capabilities, use cases, and key distinctions between services.","permalink":"/docs/ai-900/workshop-2-azure-ai/azure-ai-services"},{"id":"ai-900/workshop-4-azure-ml/azure-ml-tools","title":"2. Azure ML Development Tools and Responsible AI","description":"Explore the three development approaches in Azure ML \u2014 AutoML, Designer, and Notebooks \u2014 and understand the responsible AI tools built into the platform.","permalink":"/docs/ai-900/workshop-4-azure-ml/azure-ml-tools"},{"id":"ai-900/workshop-5-nlp/azure-nlp-services","title":"2. Azure NLP Services in Depth","description":"Deep dive into Azure AI Language and Azure AI Speech \u2014 capabilities, Conversational Language Understanding, custom models, and the exam-critical service selection scenarios for NLP workloads.","permalink":"/docs/ai-900/workshop-5-nlp/azure-nlp-services"},{"id":"ai-900/workshop-7-generative-ai/azure-openai","title":"2. Azure OpenAI Service and Prompt Engineering","description":"Master Azure OpenAI Service \u2014 available models, prompt engineering techniques, the RAG pattern, and Azure AI Foundry integration for building production generative AI applications.","permalink":"/docs/ai-900/workshop-7-generative-ai/azure-openai"},{"id":"ai-900/workshop-8-responsible-ai/azure-rai-tools","title":"2. Azure Tools for Responsible AI","description":"Azure tools that operationalize Responsible AI \u2014 the Responsible AI Dashboard in Azure ML, Azure AI Content Safety, Transparency Notes, and how to embed RAI practices across the full AI lifecycle.","permalink":"/docs/ai-900/workshop-8-responsible-ai/azure-rai-tools"},{"id":"ai-900/workshop-6-computer-vision/azure-vision-services","title":"2. Azure Vision Services in Depth","description":"Azure Vision services in depth \u2014 Azure AI Vision, Custom Vision, Face API, and Document Intelligence \u2014 with capability tables, industry use cases, and exam-critical service selection scenarios.","permalink":"/docs/ai-900/workshop-6-computer-vision/azure-vision-services"},{"id":"ai-900/workshop-3-ml-fundamentals/ml-terminology","title":"2. ML Terminology and Model Evaluation","description":"Master the essential ML vocabulary tested in AI-900 \u2014 features, labels, overfitting, underfitting, model evaluation metrics, and the train/validation/test split.","permalink":"/docs/ai-900/workshop-3-ml-fundamentals/ml-terminology"},{"id":"ai-900/workshop-8-responsible-ai/rai-case-studies-exam-prep","title":"3. Case Studies and AI-900 Exam Preparation","description":"Real-world case studies applying RAI principles across industries, plus a comprehensive AI-900 exam preparation guide covering all 8 workshops with key concepts and service selection patterns.","permalink":"/docs/ai-900/workshop-8-responsible-ai/rai-case-studies-exam-prep"},{"id":"ai-900/workshop-2-azure-ai/service-selection","title":"3. Choosing the Right Azure AI Service","description":"A systematic decision framework for selecting the right Azure AI service given a business problem \u2014 the most exam-critical skill in AI-900 Workshop 2.","permalink":"/docs/ai-900/workshop-2-azure-ai/service-selection"},{"id":"ai-900/workshop-1-intro-ai/ai-workloads","title":"3. Common AI Workloads","description":"Explore the four primary AI workload categories in the AI-900 exam: NLP, Computer Vision, Speech, and Generative AI \u2014 with definitions, capabilities, Azure service mappings, and a business problem decision table.","permalink":"/docs/ai-900/workshop-1-intro-ai/ai-workloads"},{"id":"ai-900/workshop-7-generative-ai/responsible-genai","title":"3. Responsible AI for Generative Systems","description":"Understand the unique Responsible AI risks of generative systems \u2014 hallucination, bias amplification, copyright, and deepfakes \u2014 and the Azure safety stack that mitigates them.","permalink":"/docs/ai-900/workshop-7-generative-ai/responsible-genai"},{"id":"ai-900/workshop-3-ml-fundamentals/ml-lifecycle","title":"3. The Machine Learning Lifecycle","description":"Understand the end-to-end Machine Learning lifecycle \u2014 from data collection to deployment \u2014 and the iterative nature of real-world ML projects.","permalink":"/docs/ai-900/workshop-3-ml-fundamentals/ml-lifecycle"}],"unlisted":false}}')}}]);